"""Load a list of score files and return a list of tuples of (neg, pos)

    Parameters
    ----------

    filenames : :any:`list`
        list of file paths
    func_load :
        function that can read files in the list

    Returns
    -------

    :any:`list`: [(neg,pos)] A list of tuples, where each tuple contains the
    ``negative`` and ``positive`` sceach system/probee.

    """
def load_files(filenames: Any, func_load: Any) -> object {
    if (filenames is None) {
        return None;
    }
    res = [];
    for filepath in filenames {
        try {
            res.append(func_load(filepath));
        } except Exception as e {
            raise;
        }
    }
    return res;
}

"""
    Divide cipher 16-hex digits into a list of 4 blocks(4 hex digits each)
    :param cipher_text: Ciphered text (16-Hex Digits)
    :return: Cipher text divided into a list of 4 blocks (converted to int)
    """
def get_cipher_block(cipher_text: Any) -> object {
    cipher_block = [];
    [
        cipher_block.append(int(cipher_text[i:(i + 4)], 16))
        for i in range(0, len(cipher_text), 4)
    ];
    return cipher_block;
}

"""Return File entity in Demisto format for use in entry context

    Parameters
    ----------
    main_object : dict
        The main object from a report's contents.

    Returns
    -------
    dict
        File object populated by report contents.
    """
def ec_file(main_object: Any) -> object {
    name = main_object.get('filename');
    hashes = main_object.get('hashes', {});
    md5 = hashes.get('md5');
    sha1 = hashes.get('sha1');
    sha256 = hashes.get('sha256');
    ssdeep = hashes.get('ssdeep');
    ext = main_object.get('info', {}).get('ext');
    file_ec = {
        'File': {
            'Name': name,
            'MD5': md5,
            'SHA1': sha1,
            'SHA256': sha256,
            'SSDeep': ssdeep,
            'Extension': ext
        }
    };
    return file_ec;
}

"""
    R10 Determining the surface pressure Pmax
        (Sec 5.5.4)
    For the maximum surface pressure with yield
    or angle controlled tightening techniques.
    """
def R10_yield(FMTab: Any, Apmin: Any, PG: Any) -> object {
    Pmax = 1.4 * (FMTab / Apmin);
    Sp = PG / Pmax;
    if (Sp > 1.0) {
        print('Sp > {} --> PASS'.format(Sp));
    } else {
        print('Sp < {} --> FAIL'.format(Sp));
    }
    return Pmax;
}
